def transform(grid):
    from collections import Counter

    # Find background color (most frequent)
    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] += 1
    background = max(counts, key=counts.get)

    result = []
    for row in grid:
        r = list(row)
        row_len = len(r)

        # Check if row is uniform
        is_uniform = all(cell == r[0] for cell in r)

        if is_uniform or r[-1] != background:
            # Uniform row OR row doesn't end with background → unchanged
            result.append(r)
        else:
            # Mixed row ending with background → replace trailing background segment with 1s
            suffix_start = row_len
            for i in range(row_len - 1, -1, -1):
                if r[i] == background:
                    suffix_start = i
                else:
                    break

            r[suffix_start:] = [1] * (row_len - suffix_start)
            result.append(r)

    return result
